using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;using Microsoft.Extensions.Hosting;using Microsoft.Extensions.Options;using MongoDB.Driver;using ZosyalMedya.Modules.Reactions.Application.Ports;using ZosyalMedya.Modules.Reactions.Application.Reactions;using ZosyalMedya.Modules.Reactions.Contracts;using ZosyalMedya.Modules.Reactions.Infrastructure.Configuration;using ZosyalMedya.Modules.Reactions.Infrastructure.Persistence.MongoDb;using ZosyalMedya.Modules.Reactions.Infrastructure.Persistence.PostgreSql;
namespace ZosyalMedya.Modules.Reactions.Infrastructure;
public static class DependencyInjection{public static IServiceCollection AddReactionsModule(this IServiceCollection s,IConfiguration c){s.AddOptions<ReactionsPersistenceOptions>().Bind(c.GetSection(ReactionsPersistenceOptions.SectionName)).ValidateDataAnnotations().ValidateOnStart();var o=c.GetSection(ReactionsPersistenceOptions.SectionName).Get<ReactionsPersistenceOptions>()??throw new InvalidOperationException("Reactions persistence configuration is missing.");if(o.Provider==ReactionsPersistenceProvider.PostgreSql){s.AddDbContext<ReactionsDbContext>(x=>x.UseNpgsql(o.PostgreSqlConnectionString));s.AddScoped<IReactionRepository,PostgreSqlReactionRepository>();}else{s.AddSingleton(_=>new ReactionsMongoDatabase(new MongoClient(o.MongoConnectionString).GetDatabase(o.MongoDatabaseName)));s.AddScoped(sp=>new MongoReactionRepository(sp.GetRequiredService<ReactionsMongoDatabase>().Database));s.AddScoped<IReactionRepository>(sp=>sp.GetRequiredService<MongoReactionRepository>());}s.AddScoped<SetReactionHandler>();s.AddScoped<IReactionsModule,ReactionsModule>();s.AddHostedService<Initializer>();return s;}}
internal sealed record ReactionsMongoDatabase(IMongoDatabase Database);internal sealed class Initializer(IServiceProvider p,IOptions<ReactionsPersistenceOptions>o):IHostedService{public async Task StartAsync(CancellationToken t){await using var s=p.CreateAsyncScope();if(o.Value.Provider==ReactionsPersistenceProvider.PostgreSql)await s.ServiceProvider.GetRequiredService<ReactionsDbContext>().Database.MigrateAsync(t);else await s.ServiceProvider.GetRequiredService<MongoReactionRepository>().EnsureIndexesAsync(t);}public Task StopAsync(CancellationToken t)=>Task.CompletedTask;}
